function coverLetter(opts){
  opts=opts||{};
  var name=(opts.name||'张三').trim()||'张三';
  var role=(opts.role||'前端工程师').trim()||'前端工程师';
  var company=(opts.company||'贵公司').trim()||'贵公司';
  var hi=opts.highlights||'';
  var lines=[];
  lines.push('尊敬的 '+company+' 招聘负责人：');
  lines.push('');
  lines.push('您好！我是 '+name+'，应聘'+role+'一职。');
  lines.push('');
  var hs=String(hi).split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  lines.push('在过往工作中，我主要积累如下：');
  if(hs.length){ for(var i=0;i<hs.length;i++) lines.push('• '+hs[i]); }
  else { lines.push('• 具备扎实的专业基础与项目实践经验。'); }
  lines.push('');
  lines.push('我对'+company+'的业务与团队文化深表认同，期待能贡献力量。如需作品集或进一步沟通，随时联系。');
  lines.push('');
  lines.push('此致');
  lines.push('敬礼');
  lines.push(name);
  return lines.join('\n');
}

var EXPORTS={coverLetter:coverLetter};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CoverLetterForgePure = EXPORTS; }
